   5: @ObservedV2
   6: export class Auth {
   7:   /**
   8:    * token
   9:    */
  10:   @Trace
  11:   token: string = "";
  12:   /**
  13:    * 刷新 token
  14:    */
  15:   refreshToken: string = "";
  16:   /**
  17:    * token 过期时间(秒)
  18:    */
  19:   expire: number = 0;
  20:   /**
  21:    * 刷新令牌过期时间
  22:    */
  23:   refreshExpire: number = 0;
  24:   /**
  25:    * 令牌创建时间(不来自服务端)
  26:    */
  27:   createdAt: number = Date.now();
  28: 
  29:   /**
  30:    * 构造函数，支持对接口返回的数据做空值兜底
  31:    * @param {Partial<Auth>} data - 原始认证数据
  32:    */
  33:   constructor(data?: Partial<Auth>) {
  34:     if (data) {
  35:       this.token = data.token ?? "";
  36:       this.refreshToken = data.refreshToken ?? "";
  37:       this.expire = data.expire ?? 0;
  38:       this.refreshExpire = data.refreshExpire ?? 0;
  39:       this.createdAt = data.createdAt ?? Date.now();
  40:     }
  41:   }
  42: 
  43:   /**
  44:    * 从接口响应构建安全的认证对象
  45:    * @param {Partial<Auth>} data - 接口返回的认证数据
  46:    * @returns {Auth} 已兜底的认证对象
  47:    */
  48:   static fromResponse(data: Partial<Auth>): Auth {
  49:     return new Auth(data);
  50:   }
  51: 
  52:   /**
  53:    * 检查访问令牌是否过期
  54:    * @returns {boolean} 是否过期
  55:    */
  56:   isExpired(): boolean {
  57:     const currentTime: number = Date.now();
  58:     const expirationTime: number = this.createdAt + this.expire * 1000;
  59:     return currentTime >= expirationTime;
  60:   }
  61: 
  62:   /**
  63:    * 检查刷新令牌是否过期
  64:    * @returns {boolean} 是否过期
  65:    */
  66:   isRefreshTokenExpired(): boolean {
  67:     const currentTime: number = Date.now();
  68:     const expirationTime: number = this.createdAt + this.refreshExpire * 1000;
  69:     return currentTime >= expirationTime;
  70:   }
  71: 
  72:   /**
  73:    * 检查令牌是否需要刷新（过期前15分钟）
  74:    * @returns {boolean} 是否需要刷新
  75:    */
  76:   shouldRefresh(): boolean {
  77:     const currentTime: number = Date.now();
  78:     const refreshTime: number = this.createdAt + this.expire * 1000 - 15 * 60 * 1000;
  79:     return currentTime >= refreshTime && !this.isRefreshTokenExpired();
  80:   }
  81: }
