   8: 
   9: /**
  10:  * AppStorageV2 键名
  11:  */
  12: export const BREAKPOINT_STATE_KEY: string = "breakpoint_state";
  13: 
  14: /**
  15:  * 断点规则
  16:  */
  17: const BREAKPOINT_RULES: BreakpointRule[] = [
  18:   /**
  19:    * 超小断点
  20:    */
  21:   { name: BreakpointType.XS, maxWidthVp: 320 },
  22:   /**
  23:    * 小断点
  24:    */
  25:   { name: BreakpointType.SM, maxWidthVp: 600 },
  26:   /**
  27:    * 中断点
  28:    */
  29:   { name: BreakpointType.MD, maxWidthVp: 840 },
  30:   /**
  31:    * 大断点
  32:    */
  33:   { name: BreakpointType.LG, maxWidthVp: Number.POSITIVE_INFINITY }
  34: ];
  35: 
  36: /**
  37:  * 断点顺序
  38:  */
  39: const BREAKPOINT_ORDER: BreakpointType[] = [
  40:   BreakpointType.XS,
  41:   BreakpointType.SM,
  42:   BreakpointType.MD,
  43:   BreakpointType.LG
  44: ];
  45: 
  46: /**
  47:  * 全局断点状态
  48:  */
  49: @ObservedV2
  50: export class BreakpointState {
  51:   @Trace
  52:   current: BreakpointType = BreakpointType.SM;
  53:   @Trace
  54:   windowWidthVp: number = 0;
  55: 
  56:   /**
  57:    * 更新窗口宽度并计算断点
  58:    * @param {number} windowWidthVp - 窗口宽度（vp）
  59:    * @returns {void} 无返回值
  60:    * @example
  61:   * state.updateByWidth(360);
  62:    */
  63:   updateByWidth(windowWidthVp: number): void {
  64:     this.windowWidthVp = windowWidthVp;
  65:     const next = this.resolveBreakpoint(windowWidthVp);
  66:     if (this.current !== next) {
  67:       this.current = next;
  68:     }
  69:   }
  70: 
  71:   /**
  72:    * 根据窗口宽度计算断点
  73:    * @param {number} windowWidthVp - 窗口宽度（vp）
  74:    * @returns {BreakpointType} 断点名称
  75:    */
  76:   resolveBreakpoint(windowWidthVp: number): BreakpointType {
  77:     for (const rule of BREAKPOINT_RULES) {
  78:       if (windowWidthVp < rule.maxWidthVp) {
  79:         return rule.name;
  80:       }
  81:     }
  82:     return BreakpointType.LG;
  83:   }
  84: 
  85:   /**
  86:    * 是否为超小断点
  87:    * @returns {boolean} 是否超小断点
  88:    */
  89:   isXS(): boolean {
  90:     return this.current === BreakpointType.XS;
  91:   }
  92: 
  93:   /**
  94:    * 是否为小断点
  95:    * @returns {boolean} 是否小断点
  96:    */
  97:   isSM(): boolean {
  98:     return this.current === BreakpointType.SM;
  99:   }
 100: 
 101:   /**
 102:    * 是否为中断点
 103:    * @returns {boolean} 是否中断点
 104:    */
 105:   isMD(): boolean {
 106:     return this.current === BreakpointType.MD;
 107:   }
 108: 
 109:   /**
 110:    * 是否为大断点
 111:    * @returns {boolean} 是否大断点
 112:    */
 113:   isLG(): boolean {
 114:     return this.current === BreakpointType.LG;
 115:   }
 116: 
 117:   /**
 118:    * 根据当前断点返回适配值
 119:    * @param {BreakpointValueOptions<T>} options - 断点值配置
 120:    * @param {T | undefined} defaultValue - 默认值
 121:    * @returns {T} 适配值
 122:    * @example
 123:   * state.getValue({ sm: $r("app.float.small"), md: $r("app.float.medium") });
 124:    */
 125:   getValue<T>(options: BreakpointValueOptions<T>, defaultValue?: T): T {
 126:     const index = BREAKPOINT_ORDER.indexOf(this.current);
 127:     const fallbackValue = this.getFallbackValue(options, defaultValue);
 128:     if (index < 0) {
 129:       return fallbackValue;
 130:     }
 131: 
 132:     // 优先取当前断点值
 133:     const currentValue = getValueByName(options, BREAKPOINT_ORDER[index]);
 134:     if (currentValue !== undefined) {
 135:       return currentValue;
 136:     }
 137: 
 138:     for (let i = index - 1; i >= 0; i--) {
 139:       // 向下回退：找更小断点的兜底值
 140:       const value = getValueByName(options, BREAKPOINT_ORDER[i]);
 141:       if (value !== undefined) {
 142:         return value;
 143:       }
 144:     }
 145: 
 146:     for (let i = index + 1; i < BREAKPOINT_ORDER.length; i++) {
 147:       // 向上补齐：找更大断点的兜底值
 148:       const value = getValueByName(options, BREAKPOINT_ORDER[i]);
 149:       if (value !== undefined) {
 150:         return value;
 151:       }
 152:     }
 153: 
 154:     return fallbackValue;
 155:   }
 156: 
 157:   /**
 158:    * 获取兜底值（优先默认值，其次取配置中第一个可用值）
 159:    * @param {BreakpointValueOptions<T>} options - 断点值配置
 160:    * @param {T | undefined} defaultValue - 默认值
 161:    * @returns {T} 兜底值
 162:    */
 163:   private getFallbackValue<T>(options: BreakpointValueOptions<T>, defaultValue?: T): T {
 164:     if (defaultValue !== undefined) {
 165:       return defaultValue;
 166:     }
 167: 
 168:     const orderedTypes: BreakpointType[] = [
 169:       BreakpointType.XS,
 170:       BreakpointType.SM,
 171:       BreakpointType.MD,
 172:       BreakpointType.LG
 173:     ];
 174: 
 175:     for (const type of orderedTypes) {
 176:       const value = getValueByName(options, type);
 177:       if (value !== undefined) {
 178:         return value;
 179:       }
 180:     }
 181: 
 182:     throw new Error("BreakpointValueOptions 不能为空，请至少提供一个断点值。");
 183:   }
 184: }
 185: 
 186: /**
 187:  * 获取全局断点状态实例；若不存在则创建
 188:  * @returns {BreakpointState} 全局断点状态
 189:  * @example
 190: * const state = getBreakpointState();
 191:  */
 192: export function getBreakpointState(): BreakpointState {
 193:   return AppStorageV2.connect<BreakpointState>(
 194:     BreakpointState,
 195:     BREAKPOINT_STATE_KEY,
 196:     () => new BreakpointState()
 197:   )!;
 198: }
 199: 
 200: /**
 201:  * 根据全局断点状态返回适配值
 202:  * @param {BreakpointValueOptions<T>} options - 断点值配置
 203:  * @param {T | undefined} defaultValue - 默认值
 204:  * @returns {T} 适配值
 205:  * @example
 206: * bp({ sm: $r("app.float.small"), md: $r("app.float.medium") });
 207:  */
 208: export function bp<T>(options: BreakpointValueOptions<T>, defaultValue?: T): T {
 209:   return getBreakpointState().getValue(options, defaultValue);
 210: }
 211: 
 212: /**
 213:  * 根据断点名称获取值
 214:  * @param {BreakpointValueOptions<T>} options - 断点值配置
 215:  * @param {BreakpointType} type - 断点类型
 216:  * @returns {T | undefined} 断点值
 217:  */
 218: function getValueByName<T>(options: BreakpointValueOptions<T>, type: BreakpointType): T | undefined {
 219:   if (type === BreakpointType.XS) {
 220:     return options.xs;
 221:   }
 222:   if (type === BreakpointType.SM) {
 223:     return options.sm;
 224:   }
 225:   if (type === BreakpointType.MD) {
 226:     return options.md;
 227:   }
 228:   return options.lg;
 229: }
